  "ax.kh_gst": "GST ᱪᱟᱞᱟᱱ ᱛᱮ ᱮᱢ ᱠᱟᱱ ᱴᱟᱠᱟ ᱟᱢᱟᱜ ᱤᱞᱮᱠᱴᱨᱚᱱᱤᱠ ᱠᱮᱥ ᱞᱮᱡᱟᱨ ᱨᱮ ᱦᱮᱰ ᱞᱮᱠᱟ ᱪᱟᱞᱟᱜ ᱠᱟᱱᱟ। ᱚᱱᱟ ᱛᱟᱭᱚᱢ GSTR-3B ᱥᱮᱴ-ᱚᱯᱷ ᱫᱚ ᱚᱱᱟ ᱵᱮᱵᱷᱟᱨᱚᱜ ᱠᱟᱱᱟ।",
  "ax.kh_tds": "ᱯᱮᱢᱮᱱᱴ ᱠᱷᱚᱱ ᱠᱟᱴᱤᱡ ᱠᱟᱱ TDS ᱫᱚ ᱛᱟᱭᱚᱢ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ 7 ᱛᱟᱨᱤᱠ ᱦᱟᱹᱵᱤᱡ ᱮᱢ ᱢᱮ (ᱢᱟᱨᱪ ᱨᱮᱭᱟᱜ 30 ᱮᱯᱨᱤᱞ ᱦᱟᱹᱵᱤᱡ)।",
  "ax.kh_tcs": "ᱟᱠᱷᱨᱤᱧ ᱨᱮ ᱦᱟᱛᱟᱣ ᱠᱟᱱ TCS ᱫᱚ ᱛᱟᱭᱚᱢ ᱪᱟᱸᱫᱚ ᱨᱮᱭᱟᱜ 7 ᱛᱟᱨᱤᱠ ᱦᱟᱹᱵᱤᱡ ᱮᱢ ᱢᱮ (ᱢᱟᱨᱪ ᱨᱮᱭᱟᱜ 30 ᱮᱯᱨᱤᱞ ᱦᱟᱹᱵᱤᱡ)।",
  "ax.kh_adv": "ᱮᱰᱵᱷᱟᱱᱥ ᱴᱮᱠᱥ 15 ᱡᱩᱱ, 15 ᱥᱮᱯᱴᱮᱢᱵᱚᱨ, 15 ᱰᱤᱥᱮᱢᱵᱚᱨ ᱟᱨ 15 ᱢᱟᱨᱪ ᱦᱟᱹᱵᱤᱡ; ᱥᱮᱞᱯᱷ-ᱮᱥᱮᱥᱢᱮᱱᱴ ᱴᱮᱠᱥ ᱨᱤᱴᱟᱨᱱ ᱞᱟᱦᱟ ᱨᱮ।",
  "ax.kh_gstref": "GST ᱯᱚᱨᱴᱟᱞ ᱟᱢᱟᱜ ᱠᱮᱥ ᱞᱮᱡᱟᱨ ᱠᱷᱚᱱ ᱵᱮᱝᱠ ᱨᱮ ᱨᱩᱣᱟᱹᱲ ᱮᱢ ᱠᱟᱱ ᱨᱤᱯᱷᱟᱱᱰ।",
  "ax.kh_itref": "ᱵᱮᱝᱠ ᱨᱮ ᱦᱮᱡ ᱠᱟᱱ ᱤᱱᱠᱟᱢ ᱴᱮᱠᱥ ᱨᱤᱯᱷᱟᱱᱰ।",
